import {expect} from '@playwright/test';
import {readFileSync} from 'node:fs';
import {createHash} from 'node:crypto';
export async function exerciseCollageOutput(page,info,lang){
 const t=(zh,en)=>lang==='en'?en:zh,d=()=>page.getByRole('dialog',{name:t('照片拼图','Photo collage'),exact:true}),b=(zh,en)=>d().getByRole('button',{name:t(zh,en),exact:true}),l=(zh,en)=>d().getByLabel(t(zh,en),{exact:true}),rows=()=>d().locator('.collage-output-list>li');
 const bytes=await page.evaluate(async()=>{const c=new OffscreenCanvas(80,60),ctx=c.getContext('2d');ctx.fillStyle='#6b8042';ctx.fillRect(0,0,80,60);return [...new Uint8Array(await(await c.convertToBlob()).arrayBuffer())];}),files=['One.png','Two.png','Three.png'].map(name=>({name,mimeType:'image/png',buffer:Buffer.from(bytes)}));
 await d().locator('input[type=file]').first().setInputFiles(files.slice(0,2));for(const [zh,en,v] of [['画布宽度','Canvas width','480'],['画布高度','Canvas height','320']]){await l(zh,en).fill(v);await l(zh,en).press('Tab');}await l('拼图输出格式','Collage output format').selectOption('webp');await expect(b('保存拼图作品','Save collage output')).toBeDisabled();await l('工程名称','Project name').fill('Frozen output');await b('保存到图库','Save to library').click();await expect(b('保存拼图作品','Save collage output')).toBeEnabled();await b('保存拼图作品','Save collage output').click();await expect(rows()).toHaveCount(1);await b('保存拼图作品','Save collage output').click();await expect(b('保存拼图作品','Save collage output')).toBeEnabled();await expect(rows()).toHaveCount(1);await b('预览与来源','Preview and sources').click();await expect(d().getByAltText(t('已保存拼图作品','Saved collage output'))).toBeVisible();await expect(d().locator('.collage-output-preview')).toContainText('One.png');
 const dl=page.waitForEvent('download');await b('下载作品','Download output').click();const file=await dl,data=readFileSync(await file.path());expect(file.suggestedFilename()).toMatch(/\.webp$/);expect(data.subarray(8,12).toString()).toBe('WEBP');expect(await d().locator('.collage-output-preview').innerText()).toContain(createHash('sha256').update(data).digest('hex'));
 await l('画布宽度','Canvas width').fill('640');await l('画布宽度','Canvas width').press('Tab');await expect(b('保存拼图作品','Save collage output')).toBeDisabled();await b('保存到图库','Save to library').click();await expect(b('保存拼图作品','Save collage output')).toBeEnabled();await expect(rows().first()).toContainText('480 × 320');await b('图库内拼图工程','Library collage projects').click();await l('搜索拼图工程','Search collage projects').fill('Frozen output');await b('搜索工程','Search projects').click();page.once('dialog',q=>q.accept());await b('删除工程','Delete project').click();await expect(d().locator('.collage-project-list>li')).toHaveCount(0);page.once('dialog',q=>q.accept());await b('恢复布局副本','Restore layout copy').click();await expect(l('画布宽度','Canvas width')).toHaveValue('480');await expect(b('另存拼图工程','Save project copy')).toHaveCount(0);await l('工程名称','Project name').fill('Restored copy');await b('保存到图库','Save to library').click();await expect(b('另存拼图工程','Save project copy')).toBeEnabled();await b('拼图作品库','Collage output library').click();await b('预览与来源','Preview and sources').click();await expect(d().getByAltText(t('已保存拼图作品','Saved collage output'))).toBeVisible();await d().locator('.collage-outputs').screenshot({path:info.outputPath('collage-output-'+lang+'.png')});expect(await d().evaluate(e=>e.scrollWidth<=e.clientWidth+1)).toBe(true);if(lang==='en')expect(await d().innerText()).not.toMatch(/[\u3400-\u9fff]/);
 page.once('dialog',q=>q.accept());await b('删除作品记录','Delete output record').click();await expect(rows()).toHaveCount(0);await b('保存拼图作品','Save collage output').click();await expect(rows()).toHaveCount(1);page.once('dialog',q=>q.accept());await b('删除作品记录','Delete output record').click();await expect(rows()).toHaveCount(0);await b('保存拼图作品','Save collage output').click();await expect(rows()).toHaveCount(1);page.once('dialog',q=>q.accept());await b('删除作品记录','Delete output record').click();await expect(rows()).toHaveCount(0);await b('关闭','Close').click();
 await page.locator('.studio-tool').filter({hasText:t('照片拼图','Photo collage')}).click();await b('批量拼图','Batch collage').click();const batch=()=>page.getByRole('dialog',{name:t('批量拼图','Batch collage'),exact:true}),bb=(zh,en)=>batch().getByRole('button',{name:t(zh,en),exact:true});await batch().locator('input[type=file]').first().setInputFiles(files);await batch().getByLabel(t('每组照片数','Photos per group'),{exact:true}).selectOption('2');await batch().getByLabel(t('工程名称','Project name'),{exact:true}).fill('Frozen batch');await bb('保存到图库','Save to library').click();await expect(bb('另存拼图工程','Save project copy')).toBeEnabled();await bb('开始逐页导出','Export pages').click();await expect(bb('保存已完成页到作品库','Save completed pages to output library')).toBeEnabled();await bb('保存已完成页到作品库','Save completed pages to output library').click();await expect(batch().locator('.collage-output-list>li')).toHaveCount(2);page.once('dialog',q=>q.accept());await batch().locator('.collage-output-list>li').first().getByRole('button',{name:t('恢复布局副本','Restore layout copy'),exact:true}).click();await expect(batch().getByLabel(t('每组照片数','Photos per group'),{exact:true})).toHaveValue('2');await expect(batch().locator('.batch-page')).toHaveCount(2);await expect(bb('另存拼图工程','Save project copy')).toHaveCount(0);
 // Stored outputs live independently of the project list; deleting records never touches sources.
 await bb('拼图作品库','Collage output library').click();for(let n=2;n>0;n--){page.once('dialog',q=>q.accept());await batch().getByRole('button',{name:t('删除作品记录','Delete output record'),exact:true}).first().click();await expect(batch().locator('.collage-output-list>li')).toHaveCount(n-1);}await bb('图库内拼图工程','Library collage projects').click();for(let n=2;n>0;n--){page.once('dialog',q=>q.accept());await batch().locator('.collage-project-list>li').filter({hasText:n===2?'Frozen batch':'Restored copy'}).getByRole('button',{name:t('删除工程','Delete project'),exact:true}).click();}await bb('关闭','Close').click();
}
